using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;
    private static DistributedApplication? s_app;
    private static IChatClient? s_chatClient;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        var appHost =
            await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();

        s_app = await appHost.BuildAsync();
        await s_app.StartAsync();

        s_chatClient = s_app.Services.GetRequiredService<IChatClient>();

        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (s_app is not null)
        {
            await s_app.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var reportStore = DiskBasedReportingConfiguration.CreateReportStore(
            storageRootPath: Path.Combine("TestResults", "EvalReports"));

        return DiskBasedReportingConfiguration.Create(reportStore, evaluators);
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        Assert.IsNotNull(s_chatClient);
        Assert.IsNotNull(s_reportingConfiguration);

        await using var scenario =
            await s_reportingConfiguration.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_ReturnsCoherentResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?"),
        };

        var response = await s_chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var context = new EvaluationContext
        {
            ["groundTruth"] = "The capital of France is Paris.",
        };

        await scenario.EvaluateAsync(messages, response, additionalContext: context);

        scenario.AssertAllMetricsPassMinimumScore(3);
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUpQuestions()
    {
        Assert.IsNotNull(s_chatClient);
        Assert.IsNotNull(s_reportingConfiguration);

        await using var scenario =
            await s_reportingConfiguration.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_HandlesFollowUpQuestions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire in one sentence."),
        };

        var response = await s_chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages, response);

        scenario.AssertAllMetricsPassMinimumScore(3);
    }
}

